// Author: MiYu. Source corpse and caster checks exercise consumption claims, real summons, restored handles, item use and decay events.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_corpse_tests <data-root> <fixture> [flow|spirit|items|scrolls|decay|autocast|freeze|animation-lifecycle]");std::wstring mode=argc>3?argv[3]:L"flow";if(mode!=L"flow" && mode!=L"spirit" && mode!=L"items" && mode!=L"scrolls" && mode!=L"decay" && mode!=L"autocast" && mode!=L"freeze" && mode!=L"animation-lifecycle")throw std::runtime_error("Unknown corpse mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto corpse=[&](unsigned owner,const char* code,float x,float y){return call("CreateCorpse",{call("Player",{vm.integer(owner)}),type(code),real(x),real(y),real(0)});};auto ghoul=vm.global("ghoul"),necro=vm.global("necro"),paladin=vm.global("paladin"),knight=vm.global("knight"),walker=vm.global("walker");
        if(mode==L"flow"){
            auto body=corpse(1,"ogru",96,0);require(session.corpseAvailable(body.bits),"CreateCorpse did not make a real usable body");auto g=session.units().at(ghoul.bits);call("SetWidgetLife",{ghoul,real(number(g->maxLife)-100)});float before=number(g->life);require(call("IssueImmediateOrder",{ghoul,vm.string("cannibalize")}).bits,"Source Cannibalize order was rejected");session.advance(1);require(number(g->life)>before && session.units().at(body.bits)->corpse->claimedBy==ghoul.bits,"Cannibalize did not heal and reserve the source corpse");require(!call("IssueImmediateOrder",{necro,vm.string("raisedead")}).bits,"Raise Dead stole a corpse from active Cannibalize");require(call("IssuePointOrder",{ghoul,vm.string("move"),real(64),real(0)}).bits && session.corpseAvailable(body.bits),"Interrupt did not release the corpse claim");require(call("IssueImmediateOrder",{necro,vm.string("raisedead")}).bits,"Source Raise Dead order was rejected");session.advance(1.5);unsigned skeletons=0;for(auto& [id,u]:session.units())if(u->summoner==necro.bits && u->summonAbility==ObjectData::code("Arai")){++skeletons;require(u->type==ObjectData::code("uske") && u->timedLife && u->timedLife->buff==ObjectData::code("Brai"),"Raise Dead lost source skeleton type or lifetime");}require(skeletons==2 && !call("GetUnitTypeId",{body}).bits,"Raise Dead did not consume one corpse for two real skeletons");auto ally=corpse(0,"hfoo",96,-256);require(call("IssueImmediateOrder",{paladin,vm.string("resurrection")}).bits,"Source Resurrection order was rejected");session.advance(1.5);require(session.units().contains(ally.bits) && number(session.units().at(ally.bits)->life)>0 && !session.units().at(ally.bits)->corpse && session.units().at(ally.bits)->foodCounted,"Resurrection did not restore the original unit and population");std::cout<<"PASS corpse_claim_heal_interrupt_raise_dead_and_resurrection\n";
        }else if(mode==L"spirit"){
            auto target=corpse(0,"ospw",96,512);auto u=session.units().at(target.bits);require(call("IssueTargetOrder",{walker,vm.string("ancestralspirittarget"),target}).bits,"Source Ancestral Spirit target order was rejected");session.advance(1.5);require(number(u->life)==number(u->maxLife) && std::abs(number(u->mana)-number(u->maxMana)*.25f)<.01f,"Ancestral Spirit ignored source restoration factors");auto enemy=corpse(1,"ogru",96,-512);require(call("IssueImmediateOrder",{knight,vm.string("animatedead")}).bits,"Source Animate Dead order was rejected");session.advance(1.5);std::uint32_t animated=0;for(auto& [id,unit]:session.units())if(unit->summoner==knight.bits && unit->summonAbility==ObjectData::code("AUan")){animated=id;require(unit->invulnerable && !unit->useFood && unit->noCorpse && unit->timedLife,"Animate Dead lost source invulnerability, food or expiry");}require(animated && !call("GetUnitTypeId",{enemy}).bits,"Animate Dead did not consume the original corpse");session.advance(40.5);require(!session.units().contains(animated) || number(session.units().at(animated)->life)==0,"Animate Dead did not expire");std::cout<<"PASS ancestral_spirit_and_animate_dead_lifetime\n";
        }else if(mode==L"items"){
            auto target=corpse(0,"hfoo",96,0);auto item=call("CreateItem",{type("rre1"),real(0),real(0)});require(call("UnitAddItem",{ghoul,item}).bits && !call("GetItemTypeId",{item}).bits && number(session.units().at(target.bits)->life)>0,"Resurrection rune did not activate without inventory and consume itself");target=corpse(0,"hfoo",96,-256);item=call("UnitAddItemById",{paladin,type("cosl")});require(item.bits && call("UnitUseItem",{paladin,item}).bits && session.items().contains(item.bits) && number(session.units().at(target.bits)->life)>0,"Original resurrection orb did not restore a unit and remain reusable");require(!call("UnitUseItem",{paladin,item}).bits,"Resurrection orb ignored cooldown");std::cout<<"PASS resurrection_rune_and_orb_inventory_consumers\n";
        }else if(mode==L"animation-lifecycle"){
            auto unit=call("CreateUnit",{call("Player",{vm.integer(0)}),type("hfoo"),real(96),real(-256),real(0)});require(session.units().contains(unit.bits),"Lifecycle unit unavailable");auto state=session.units().at(unit.bits);auto before=state->animationGeneration;call("SetWidgetLife",{unit,real(0)});require(session.units().contains(unit.bits) && state->corpse && state->animationGeneration>before,"Death did not restart its animation");before=state->animationGeneration;auto delay=state->corpse->death;session.advance(delay+.1);require(session.units().contains(unit.bits) && state->corpse && state->corpse->phase==CorpseState::Phase::Flesh && state->animationGeneration>before,"Corpse decay did not restart its animation");before=state->animationGeneration;call("SetWidgetLife",{unit,real(100)});require(session.units().contains(unit.bits) && !state->corpse && state->animationGeneration>before,"Revived corpse did not restart its animation");std::cout<<"PASS lifecycle_death_decay_resurrection_animation_generation\n";
        }else if(mode==L"scrolls"){
            auto ally=corpse(0,"hfoo",96,-256);auto scroll=call("UnitAddItemById",{paladin,type("srrc")});require(scroll.bits && call("UnitUseItem",{paladin,scroll}).bits,"Resurrection scroll use failed");require(!session.items().contains(scroll.bits) && session.units().contains(ally.bits) && number(session.units().at(ally.bits)->life)>0 && !session.units().at(ally.bits)->corpse,"Resurrection scroll did not consume itself and restore the original corpse");
            for(auto code:{"sand","scul"}){auto enemy=corpse(1,"ogru",96,-256);scroll=call("UnitAddItemById",{paladin,type(code)});require(scroll.bits && call("UnitUseItem",{paladin,scroll}).bits,"Animate Dead scroll use failed");require(!session.items().contains(scroll.bits) && !call("GetUnitTypeId",{enemy}).bits,"Animate Dead scroll did not consume itself and its corpse");std::uint32_t animated=0;for(auto& [id,unit]:session.units())if(unit->summoner==paladin.bits && unit->summonAbility==ObjectData::code("AIan") && number(unit->life)>0){require(!animated,"Animate Dead scroll produced unexpected extra units");animated=id;require(unit->invulnerable && !unit->useFood && unit->noCorpse && unit->timedLife,"Animate Dead scroll lost invulnerability, food or expiry");}require(animated,"Animate Dead scroll did not create a unit");session.advance(40.5);require(!session.units().contains(animated) || number(session.units().at(animated)->life)==0,"Animate Dead scroll unit did not expire");}std::cout<<"PASS corpse_scroll_consumption_and_lifetime\n";
        }else if(mode==L"freeze"){
            auto body=corpse(1,"hfoo",96,0);session.advance(5);auto u=session.units().at(body.bits);double age=u->corpse->elapsed;auto phase=u->corpse->phase;call("UnitSuspendDecay",{body,vm.boolean(true)});session.advance(1);require(u->corpse->elapsed==age && u->corpse->phase==phase,"Late decay suspension rewound the corpse clock or pose");call("UnitSuspendDecay",{body,vm.boolean(false)});session.advance(1);require(std::abs(u->corpse->elapsed-age-1)<.0001,"Resumed corpse decay did not continue from its saved age");std::cout<<"PASS late_corpse_decay_suspend_and_resume\n";
        }else if(mode==L"autocast"){
            auto body=corpse(1,"ogru",96,256);require(call("IssueImmediateOrder",{necro,vm.string("raisedeadon")}).bits,"Raise Dead source autocast toggle was rejected");session.advance(2);require(!call("GetUnitTypeId",{body}).bits,"Raise Dead autocast did not consume its target");unsigned skeletons=0;for(auto& [id,u]:session.units())if(u->summoner==necro.bits && u->summonAbility==ObjectData::code("Arai"))++skeletons;require(skeletons==2,"Raise Dead autocast did not create source skeletons");std::cout<<"PASS raise_dead_source_autocast\n";
        }else{
            auto body=corpse(1,"hfoo",96,0);call("UnitSuspendDecay",{body,vm.boolean(true)});session.advance(60);session.advance(31);require(session.corpseAvailable(body.bits) && !vm.global("decays").bits,"Suspended corpse continued natural decay");call("UnitSuspendDecay",{body,vm.boolean(false)});session.advance(60);session.advance(31);require(!call("GetUnitTypeId",{body}).bits && !call("GetWidgetLife",{body}).bits && vm.global("decays").bits==1 && vm.global("decaying").bits==body.bits,"Natural corpse decay did not emit real context or clear its handle");std::cout<<"PASS suspended_decay_native_event_and_handle_cleanup\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
